const menuIconPaths={soc:'M3 12h4l3-8 4 16 3-8h4 M3 3h18v18H3z',content:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',assets:'M3 7h7l2 3h9v11H3z M3 7V3h7l2 3h9v4',calendar:'M4 5h16v16H4z M8 2v6 M16 2v6 M4 10h16',inbox:'M4 4h16v16H4z M4 14h5l2 3h2l2-3h5',listening:'M4 14v-4 M8 18V6 M12 22V2 M16 18V6 M20 14v-4',analytics:'M4 3v18h18 M8 16v-4 M13 16V8 M18 16V5',ads:'m3 10 14-6v16L3 14z M7 16l2 5h4l-2-4 M21 9v6',users:'M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M2 22v-4a7 7 0 0 1 14 0v4 M17 4a4 4 0 0 1 0 8 M19 16a6 6 0 0 1 3 5',audit:'M5 3h14v18H5z M8 7h8 M8 12h8 M8 17h5',preferences:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',collapse:'m14 6-6 6 6 6 M3 3h18v18H3z'};
const menuIcon=name=>`<svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${menuIconPaths[name]||menuIconPaths.content}"/></svg>`;
let navState={rail:false,sections:[]};
function readNavState(){try{navState=JSON.parse(localStorage.getItem('ngyn-navigation-'+viewUser))||{rail:false,sections:[]}}catch{navState={rail:false,sections:[]}}}
function saveNavState(){localStorage.setItem('ngyn-navigation-'+viewUser,JSON.stringify(navState))}
menuMarkup=function(){return navSections.map(([title,entries])=>{const available=entries.filter(e=>pageAllowed(e[0]));const expanded=navState.rail||!navState.sections.includes(title);return available.length?`<div class="menu-section"><button class="menu-section-toggle" data-menu-section="${title}" aria-expanded="${expanded}"><span>${title}</span><span class="section-chevron">${expanded?'⌄':'›'}</span></button><div class="menu-items" ${expanded?'':'hidden'}>${available.map(e=>`<button data-go="${e[0]}" ${e[0]==='assets'?'id="groups-nav"':e[0]==='users'?'id="users-nav"':''} class="${currentPage===e[0]?'active':''}" title="${e[1]}" aria-label="${e[1]}" ${currentPage===e[0]?'aria-current="page"':''}>${menuIcon(e[0])}<span class="menu-text">${e[1]}</span><span class="menu-tooltip">${e[1]}</span></button>`).join('')}</div></div>`:''}).join('')};
const renderBeforeNavigation=renderWorkspace;renderWorkspace=function(page=currentPage){readNavState();document.documentElement.classList.toggle('sidebar-collapsed',navState.rail);renderBeforeNavigation(page);window.scrollTo({top:0,behavior:'instant'});const brand=document.querySelector('.sidebar .brand');if(brand){const toggle=document.createElement('button');toggle.className='collapse-sidebar';toggle.id='sidebar-collapse';toggle.title=navState.rail?'Expand sidebar':'Collapse sidebar';toggle.setAttribute('aria-label',toggle.title);toggle.setAttribute('aria-expanded',String(!navState.rail));toggle.innerHTML=menuIcon('collapse');brand.insertAdjacentElement('afterend',toggle);toggle.onclick=()=>{navState.rail=!navState.rail;saveNavState();renderWorkspace(currentPage)}}document.querySelectorAll('[data-menu-section]').forEach(b=>b.onclick=()=>{const title=b.dataset.menuSection;navState.sections=navState.sections.includes(title)?navState.sections.filter(s=>s!==title):[...navState.sections,title];saveNavState();renderWorkspace(currentPage)});const pref=document.querySelector('.sidebar-preferences [data-go]');if(pref){pref.innerHTML=menuIcon('preferences')+'<span class="menu-text">My preferences</span><span class="menu-tooltip">My preferences</span>';pref.title='My preferences';pref.setAttribute('aria-label','My preferences')}const settings=document.querySelector('.topbar [data-go="preferences"]');if(settings)settings.innerHTML=menuIcon('preferences');document.querySelectorAll('.menu-items [data-go]').forEach(b=>{const item=navSections.flatMap(s=>s[1]).find(e=>e[0]===b.dataset.go);if(item)b.innerHTML=menuIcon(item[0])+'<span class="menu-text">'+item[1]+'</span><span class="menu-tooltip">'+item[1]+'</span>'});document.querySelectorAll('[data-go] .menu-tooltip').forEach(t=>{const b=t.parentElement;const position=()=>{t.style.top=b.getBoundingClientRect().top+'px'};b.addEventListener('mouseenter',position);b.addEventListener('focus',position)})};
const samplePhotos=[{image:'photo-1760276049745-c45e982a8065',author:'Kristaps Ungurs',source:'https://unsplash.com/photos/cup7nWOyhAA',alt:'Autumn woodland path with fallen leaves.'},{image:'photo-1742069207552-287bd7359a50',author:'Zoshua Colah',source:'https://unsplash.com/photos/two-buses-are-driving-down-a-street-GTI-duKwNBU',alt:'City buses travelling along a street.'},{image:'photo-1759237571484-463dd9ed8d12',author:'Kelsey He',source:'https://unsplash.com/photos/XdGhGTW_g8w',alt:'Wooden walkway through a forest of autumn trees.'},{image:'photo-1579970018561-4ceaecacdcec',author:'Michael Discenza',source:'https://unsplash.com/photos/gW33MQrtJvM',alt:'City skyline across a lake at sunset.'}];
function samplePhoto(index,w=1100,h){const p=samplePhotos[Math.abs(index)%samplePhotos.length];return 'https://images.unsplash.com/'+p.image+'?auto=format&fit=crop&q=80&w='+w+(h?'&h='+h:'')}
function photoCredit(index){const p=samplePhotos[Math.abs(index)%samplePhotos.length];return `<span class="photo-credit">Sample photo: <a href="${p.source}" target="_blank" rel="noopener noreferrer">${p.author} / Unsplash</a> · illustrative location</span>`}
const postBeforePhotos=postMarkup;postMarkup=function(p){let markup=postBeforePhotos(p),photo=samplePhotos[(p.art||0)%samplePhotos.length];markup=markup.replaceAll(profileArt(p.art),samplePhoto(p.art));markup=markup.replaceAll('alt="'+safe(p.alt)+'"','alt="'+safe(photo.alt)+'" loading="lazy" referrerpolicy="no-referrer"');markup=markup.replace('fictional media · no fabricated metrics','sample photo · no fabricated metrics');return markup.replace('<div class="native-disclaimer">',photoCredit(p.art)+'<div class="native-disclaimer">')};
function visualReference(sizeIndex,sampleIndex){const [label,w,h]=commonSizes[sizeIndex],photo=samplePhoto(sizeIndex+sampleIndex,Math.min(w,1200),Math.round(Math.min(w,1200)*h/w));return photo}
const brandModeBeforePhotos=renderBrandMode;renderBrandMode=function(mode){brandModeBeforePhotos(mode);if(mode==='visuals'){document.querySelectorAll('[data-reference]').forEach(b=>{const [i,j]=b.dataset.reference.split('-').map(Number);b.querySelector('img').src=visualReference(i,j);b.querySelector('img').alt=samplePhotos[(i+j)%samplePhotos.length].alt;b.onclick=()=>{const [label,w,h]=commonSizes[i],board=brandBoard(),set=board.sets.find(s=>s.id===board.selected);modal(`<div class="modal-head"><h2>${label} · visual reference</h2><button data-close aria-label="Close">×</button></div><img class="reference-large" style="aspect-ratio:${w}/${h};object-fit:cover" src="${visualReference(i,j)}" alt="${safe(samplePhotos[(i+j)%samplePhotos.length].alt)}" referrerpolicy="no-referrer">${photoCredit(i+j)}<p class="ops-muted">Working canvas: ${w} × ${h}. Generic crop reference; validate the destination channel’s current requirements.</p><p class="ops-muted">Attach to: ${safe(set.name)}</p><button class="btn primary" id="attach-reference">Use in this guideline</button>`);document.querySelector('#attach-reference').onclick=()=>{const ref={key:i+'-'+j,setId:set.id,label,width:w,height:h,photoSource:samplePhotos[(i+j)%samplePhotos.length].source,image:visualReference(i,j)};if(!board.refs.some(r=>r.key===ref.key&&r.setId===ref.setId))board.refs.push(ref);saveOps();toast('Reference attached to '+set.name+'.');close()}}});const note=document.createElement('p');note.className='ops-muted';note.textContent='Free Unsplash sample photos. Open a reference to view its credit and attach it to the selected guideline.';document.querySelector('#brand-editor-content').prepend(note)}};
const compileBeforeReferences=compiledBrand;compiledBrand=function(board,set){return {...compileBeforeReferences(board,set),selectedVisualReferences:board.refs.filter(r=>r.setId===set.id)}};
samplePhotos.push({image:'photo-1558617320-e695f0d420de',author:'Thomas Park',source:'https://unsplash.com/photos/swimming-pool-close-up-photography-QGdRrty4054',alt:'Clear blue swimming pool water over lane markings.'});
renderWorkspace(currentPage);
